            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None
            self.type = None

    @staticmethod
    def get_objects(path):
        objects = []
        object_paths = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))
                object_paths.append(object_path)

        Object.set_types(objects, object_paths)

        return objects

    @staticmethod
    def set_types(objects, object_paths):
        for index, object in enumerate(objects):
            if object.type is None:
                object.type = Object.guess_type(object_paths[index])

    @staticmethod
    def guess_type(path):
        # TODO Limit extension length to 10?
        extension = os.path.splitext(path)[1].lstrip('.')
        if len(extension) > 0 and len(extension) <= 10:
            try:
                # TODO Handle unicode paths
                stream = open(path, 'rb')
                sample = stream.read(82944)
                kind = chardet.detect(sample)['encoding']
                if kind:
                    return 'text/html'
            except IOError:
                logger.error('Failed to guess the type of "%s"', path)
            except WindowsError:
                logger.error('Failed to guess the type of "%s". Permission denied', path)

        return 'application/octet-stream'

